insert into public.recipe_steps (id, recipe_id, position, text, created_at, updated_at) values
  ('omleta-spanac-feta:s1', 'omleta-spanac-feta', 0, 'Bate ouăle cu sare și piper.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('omleta-spanac-feta:s2', 'omleta-spanac-feta', 1, 'Călește spanacul în uleiul de măsline timp de 1 minut, toarnă ouăle și presară brânza feta sfărâmată.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('omleta-spanac-feta:s3', 'omleta-spanac-feta', 2, 'Gătește la foc mic până se încheagă și împăturește.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('terci-ovaz-fructe-padure-unt-arahide:s1', 'terci-ovaz-fructe-padure-unt-arahide', 0, 'Fierbe ovăzul în lapte la foc mic timp de 5-7 minute, amestecând continuu până absoarbe lichidul.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('terci-ovaz-fructe-padure-unt-arahide:s2', 'terci-ovaz-fructe-padure-unt-arahide', 1, 'Transferă într-un bol și adaugă fructele de pădure, untul de arahide și mierea.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('toast-avocado-ou-posat:s1', 'toast-avocado-ou-posat', 0, 'Prăjește pâinea.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('toast-avocado-ou-posat:s2', 'toast-avocado-ou-posat', 1, 'Pasează miezul de avocado cu zeama de lămâie, sare și piper.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('toast-avocado-ou-posat:s3', 'toast-avocado-ou-posat', 2, 'Întinde pasta pe felii și așază deasupra ouăle poșate în apă aproape de punctul de fierbere timp de 3 minute.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('clatite-americane-banane-pancakes:s1', 'clatite-americane-banane-pancakes', 0, 'Pasează banana, amestecă cu oul și laptele, apoi încorporează făina de ovăz, praful de copt și scorțișoara.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('clatite-americane-banane-pancakes:s2', 'clatite-americane-banane-pancakes', 1, 'Coace clătite mici într-o tigaie antiaderentă câte 2 minute pe fiecare parte.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('budinca-chia-mango-cocos:s1', 'budinca-chia-mango-cocos', 0, 'Amestecă semințele de chia cu laptele de cocos și siropul de arțar.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('budinca-chia-mango-cocos:s2', 'budinca-chia-mango-cocos', 1, 'Lasă la frigider minimum 4 ore sau peste noapte, iar dimineața adaugă cuburile de mango deasupra.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('shakshuka-oua-sos-rosii:s1', 'shakshuka-oua-sos-rosii', 0, 'Călește ceapa, ardeiul și usturoiul în ulei, adaugă roșiile și condimentele și fierbe 10 minute.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('shakshuka-oua-sos-rosii:s2', 'shakshuka-oua-sos-rosii', 1, 'Fă 4 adâncituri, sparge ouăle în ele, acoperă cu un capac și gătește 5-6 minute până se albesc albușurile.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('sandwich-cald-curcan-cascaval-panini:s1', 'sandwich-cald-curcan-cascaval-panini', 0, 'Taie chifla pe lungime, unge-o cu muștar, așază curcanul, cașcavalul, feliile de roșie și rucola.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('sandwich-cald-curcan-cascaval-panini:s2', 'sandwich-cald-curcan-cascaval-panini', 1, 'Rumenește sandwich-ul într-un grill electric sau într-o tigaie presată timp de 4-5 minute.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('iaurt-grecesc-granola-nuci:s1', 'iaurt-grecesc-granola-nuci', 0, 'Pune iaurtul grecesc într-un bol, presară granola crocantă și miezul de nucă rupt bucăți, apoi stropește cu miere.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('scramble-tofu-turmeric-legume:s1', 'scramble-tofu-turmeric-legume', 0, 'Sfărâmă tofu cu o furculiță.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('scramble-tofu-turmeric-legume:s2', 'scramble-tofu-turmeric-legume', 1, 'Călește legumele tăiate mărunt 3 minute, adaugă tofu, turmericul, sarea și drojdia inactivă și gătește încă 5-7 minute amestecând constant.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('friganele-french-toast-scortisoara:s1', 'friganele-french-toast-scortisoara', 0, 'Bate oul cu laptele, vanilia și scorțișoara.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('friganele-french-toast-scortisoara:s2', 'friganele-french-toast-scortisoara', 1, 'Înmoaie feliile de pâine pe ambele părți și prăjește-le în untul încins câte 2 minute pe fiecare parte până devin aurii.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('smoothie-bowl-verde-energizant:s1', 'smoothie-bowl-verde-energizant', 0, 'Mixează banana, avocado, spanacul și băutura de migdale până obții o cremă densă.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('smoothie-bowl-verde-energizant:s2', 'smoothie-bowl-verde-energizant', 1, 'Toarnă în bol și decorează cu feliile de kiwi și semințele de dovleac.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('omleta-rulada-somon-afumat-crema-branza:s1', 'omleta-rulada-somon-afumat-crema-branza', 0, 'Coace o omletă subțire dintr-o singură bucată într-o tigaie antiaderentă.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('omleta-rulada-somon-afumat-crema-branza:s2', 'omleta-rulada-somon-afumat-crema-branza', 1, 'Las-o să se tempereze 2 minute, unge-o cu crema de brânză, așază somonul și mărarul, rulează strâns și taie rondele.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('lipie-integrala-omleta-fasole-neagra-burrito:s1', 'lipie-integrala-omleta-fasole-neagra-burrito', 0, 'Gătește ouăle bătute sub formă de jumări cremoase.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('lipie-integrala-omleta-fasole-neagra-burrito:s2', 'lipie-integrala-omleta-fasole-neagra-burrito', 1, 'Încălzește lipia 20 de secunde, așază ouăle, fasolea neagră, brânza rasă și salsa, apoi rulează strâns cu marginile pliate spre interior.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('branza-cottage-ridichi-ceapa-verde:s1', 'branza-cottage-ridichi-ceapa-verde', 0, 'Taie ridichile cubulețe și ceapa verde rondele fine, amestecă-le cu brânza cottage, asezonează cu sare și piper și servește alături de feliile de pâine prăjită.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
  ('oua-coapte-in-avocado:s1', 'oua-coapte-in-avocado', 0, 'Taie avocado în jumătate, scoate sâmburele și scobește câte o linguriță din miez pentru a face loc oului.', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z'),
